<?php
 if ( ! defined( 'ABSPATH' ) ) { exit; } add_action( 'elementor/elements/categories_registered', function ( $mgr ) { $mgr->add_category( 'hivemind-mixer', array( 'title' => 'Hivemind Mixer', 'icon' => 'eicon-calendar', ) ); } ); add_action( 'elementor/widgets/register', function ( $widgets_manager ) { $dir = HVM_DIR . '/inc/widgets/'; if ( ! is_dir( $dir ) ) { return; } foreach ( glob( $dir . 'class-*.php' ) as $file ) { require_once $file; } $classes = apply_filters( 'hvm_mixer_widget_classes', array() ); foreach ( $classes as $class ) { if ( class_exists( $class ) ) { $widgets_manager->register( new $class() ); } } } ); 